#include <vector>
using namespace std;

class Solution {
public:
    long long minOperations(vector<int>& nums) {
        long long ops = 0;
        long long cur = nums[0];
        for (size_t i = 1; i < nums.size(); ++i) {
            if (nums[i] <= cur) {
                long long needed = cur + 1;
                ops += needed - nums[i];
                cur = needed;
            } else {
                cur = nums[i];
            }
        }
        return ops;
    }
};

class Solution {
    public long minOperations(int[] nums) {
        long ops = 0;
        long cur = nums[0];
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] <= cur) {
                long needed = cur + 1;
                ops += needed - nums[i];
                cur = needed;
            } else {
                cur = nums[i];
            }
        }
        return ops;
    }
}

var minOperations = function(nums) {
